from concurrent.futures import ThreadPoolExecutor


def square(x: int) -> int:
    return x * x


def squares(xs: list[int]) -> list[int]:
    """Square every element of xs in parallel using a thread pool.

    The result preserves the order of the input list. The input list is
    not modified. An empty list yields an empty list.
    """
    with ThreadPoolExecutor() as pool:
        return list(pool.map(square, xs))


def test_squares_basic() -> None:
    assert squares([1, 2, 3, 4]) == [1, 4, 9, 16]


def test_squares_empty() -> None:
    assert squares([]) == []


def test_squares_negative_and_zero() -> None:
    assert squares([-3, 0, 5]) == [9, 0, 25]


def test_squares_preserves_order() -> None:
    xs = list(range(100, 0, -1))
    assert squares(xs) == [x * x for x in xs]


def test_squares_large_values() -> None:
    big = 10**12
    assert squares([big, -big]) == [big * big, big * big]


def test_squares_does_not_mutate_input() -> None:
    xs = [1, 2, 3]
    copy = list(xs)
    result = squares(xs)
    assert xs == copy
    assert result is not xs


def test_squares_many_elements() -> None:
    xs = list(range(1000))
    assert squares(xs) == [x * x for x in xs]


def test_squares_duplicates() -> None:
    assert squares([2, 2, -2, 2]) == [4, 4, 4, 4]
